<?php require_once __DIR__.'/includes/bootstrap.php';require_manager();$pdo=db();$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['full_name']);$username=trim($_POST['username']);$pass=$_POST['password'];$role=$_POST['role'];if(strlen($pass)<8)$err='Password must contain at least 8 characters.';elseif(!in_array($role,['manager','cashier'],true))$err='Invalid role.';else try{$s=$pdo->prepare('INSERT INTO users(full_name,username,password_hash,role) VALUES(?,?,?,?)');$s->execute([$name,$username,password_hash($pass,PASSWORD_DEFAULT),$role]);$msg='Staff account created.';}catch(Throwable $e){$err='Could not create account. Check that the username is not already used.';}}$rows=$pdo->query('SELECT id,full_name,username,role,is_active,created_at FROM users ORDER BY id')->fetchAll();$pageTitle='Staff';require 'includes/header.php';?>
<?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert danger"><?=e($err)?></div><?php endif;?><div class="panel"><h2>Create staff account</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div><label>Full name</label><input name="full_name" required></div><div><label>Username</label><input name="username" required></div><div><label>Temporary password</label><input name="password" type="password" minlength="8" required></div><div><label>Role</label><select name="role"><option value="cashier">Cashier</option><option value="manager">Manager</option></select></div><div class="form-action"><button class="btn primary">Create account</button></div></form></div><div class="panel"><h2>Staff accounts</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Role</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['username'])?></td><td><?=e(ucfirst($r['role']))?></td><td><?=$r['is_active']?'Active':'Disabled'?></td></tr><?php endforeach;?></tbody></table></div></div><?php require 'includes/footer.php';?>
